# member pvros4s2_tta: model-v2x-track/pvrcnnpp-ros-g1v4-s2, checkpoint md5 30b8d6036c6f2c4b8d9de562d0f2e6a5
python common/tools/pcdet_predict.py model-v2x-track/pvrcnnpp-ros-g1v4-s2 --ckpt model-v2x-track/pvrcnnpp-ros-g1v4-s2/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames kit --postprocess model-v2x-track/pvrcnnpp-ros-g1v4-s2/test/postprocess_tta.yaml --tta flip4+yaw+z --out $OUT/predictions_pvros4s2_tta.json
