python common/tools/route_predictions.py merge model-v2x-track/routed-g15 --pred bagpv5=$OUT/predictions_bagpv5.json --pred bagpv5x_tta=$OUT/predictions_bagpv5x_tta.json --pred bagvr5_tta=$OUT/predictions_bagvr5_tta.json --pred pp5_tta=$OUT/predictions_pp5_tta.json --pred pvros4s2_tta=$OUT/predictions_pvros4s2_tta.json --pred vrros_tta12=$OUT/predictions_vrros_tta12.json --out $OUT/predictions.json
