if [ -d "$BDC_DATA/v2x-track/pcdet/g1-v5/points" ]; then SYN=(--syn-split val --syn-list model-v2x-track/routed-g15/submissions/2026-11-02_s9a/synthetic_ids.txt); else SYN=(--syn-zip model-v2x-track/routed-g15/submissions/2026-11-02_s9a/v2x_s9a_submission.zip --syn-list model-v2x-track/routed-g15/submissions/2026-11-02_s9a/synthetic_ids.txt); fi
